import { expect, test, uniqueName } from "../../fixtures";

test("the vendor with an unreadable expiry date is listed above the other", { tag: "@UI-09" }, async ({ pages, signIn, factory }) => {
  // Arrange
  const unreadable = uniqueName("Unreadable Expiry");
  const readable = uniqueName("Readable Expiry");
  await factory.vendorInReview({ name: unreadable, files: { insurance_certificate: "insurance_certificate_unparseable.txt" } });
  await factory.vendorInReview({ name: readable });
  await signIn("reviewer");

  // Act
  await pages.reviewQueue.goto();

  // Assert
  await expect(pages.reviewQueue.card(unreadable)).toBeVisible();
  await expect(pages.reviewQueue.card(readable)).toBeVisible();
  const aboveBox = await pages.reviewQueue.card(unreadable).boundingBox();
  const belowBox = await pages.reviewQueue.card(readable).boundingBox();
  expect(aboveBox, "unreadable-date card has a layout box").not.toBeNull();
  expect(belowBox, "readable-date card has a layout box").not.toBeNull();
  expect(aboveBox!.y, "unreadable-date vendor is listed above the other").toBeLessThan(belowBox!.y);
});
